do $$begin begin perform public.save_profile_identity('DPS',null,'{"full_name":"[CONTOH] Missing","email":"missing.profile.qa@example.invalid","npp":null,"is_active":false}');raise exception 'Expected missing Auth rejection';exception when sqlstate 'P0001' then if sqlerrm='Expected missing Auth rejection' then raise;end if;end;end $$;
select set_config('request.jwt.claim.sub','ef100000-0000-4000-8000-000000000002',true);
do $$begin begin perform public.save_profile_identity('DPS',null,'{}');raise exception 'Expected role denial';exception when insufficient_privilege then null;end;end $$;
reset role;
select pass('Profile identity create/edit, NPP mapping, missing Auth and RBAC');
select * from finish();
rollback;
